function Brand({small=false}) {return <span className={`brand ${small?'small':''}`}><Logo/>{!small&&<span>multicord<span className="brand-dot">.</span></span>}</span>}
// status : true (en ligne) ou 'online' | 'idle' | 'dnd' | 'invisible'.
function Avatar({user,size=36,status=false}) {return <ProfilePicture user={user} style={{width:size,height:size,color:'#293029',fontSize:size*.34}}>{status&&<i className={typeof status==='string'?`presence-${status}`:undefined}/>}</ProfilePicture>}
const PRESENCES=[['online','En ligne',null],['idle','Absent','Vous apparaissez absent, même en activité.'],['dnd','Ne pas déranger','Vous ne recevrez aucune notification de bureau.'],['invisible','Invisible','Vous apparaîtrez hors ligne, mais aurez accès à toutes les fonctionnalités.']];
const presenceLabel=p=>PRESENCES.find(x=>x[0]===p)?.[1]||'En ligne';

function IconButton({icon:Icon,label,onClick,active=false,...props}) {return <button type="button" className={`icon-button ${active?'active':''}`} title={label} aria-label={label} onClick={onClick} {...props}><Icon size={19}/></button>}
// Accepte un code brut, un lien https://…/invite/CODE, l'ancien ?invite=CODE ou multicord://invite/CODE.
export const parseInvite=value=>{const v=String(value||'').trim();return v.match(/invite[/=]([A-Za-z0-9]{6,32})/)?.[1]||v;};
const inviteInUrl=()=>location.pathname.match(/^\/invite\/([A-Za-z0-9]{6,32})\/?$/)?.[1]||new URLSearchParams(location.search).get('invite');
const formatDate=value=>new Date(value).toLocaleString('fr-FR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
function Modal({title,subtitle,onClose,children}) {return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className="modal" role="dialog" aria-modal="true" aria-label={title}><IconButton icon={X} label="Fermer" onClick={onClose}/><div className="modal-symbol"><Brand small/></div><h2>{title}</h2><p className="muted">{subtitle}</p>{children}</section></div>}

