  async function action(fn) {setBusy(true);setError('');try{await fn();}catch(e){setError(e.message);}finally{setBusy(false);}}
  function leave(){wantedVoice.current=null;reconnecting.current++;voiceRef.current?.destroy();voiceRef.current=null;setVoice(null);setMedia(null);setCamera(false);setSharing(false);setMuted(false);}
  async function connectVoice(target){const v=new VoiceSession(socket.current,boot.rtc,m=>{setMedia(m);setSharing(!!m.screen);},notify,()=>reconnectRef.current?.());voiceRef.current=v;try{v.configure(preferences,devices);await v.join(target.channel);}catch(e){v.destroy();if(voiceRef.current===v)voiceRef.current=null;throw e;}}
  async function joinVoice(ch){if(voice?.channel===ch.id&&!voice.reconnecting)return;if(voice)leave();await action(async()=>{const target={channel:ch.id,name:ch.name,serverName:server.name,serverId:server.id};await connectVoice(target);wantedVoice.current=target;setVoice(target);setMuted(false);});}
  // Reconnexion automatique (hôte parti, réseau coupé, média perdu) : quelques essais espacés, puis abandon.
  async function reconnectVoice(){
    const target=wantedVoice.current;if(!target)return;const token=++reconnecting.current;
    voiceRef.current?.destroy();voiceRef.current=null;setMedia(null);setCamera(false);setSharing(false);setVoice({...target,reconnecting:true});
    let last;for(const delay of [300+Math.random()*900,2000,4000,8000,15000]){
      await new Promise(r=>setTimeout(r,delay));if(token!==reconnecting.current)return;if(!socket.current?.connected)return;
      try{await connectVoice(target);if(token!==reconnecting.current){voiceRef.current?.destroy();voiceRef.current=null;return;}setVoice(target);notify('Reconnecté au salon vocal.');return;}
      catch(e){last=e;if(/inaccessible|limité/i.test(e.message))break;}
    }
    if(token===reconnecting.current){wantedVoice.current=null;setVoice(null);setMedia(null);setError('Reconnexion au vocal impossible'+(last?` : ${last.message}`:'.'));}
  }
  reconnectRef.current=reconnectVoice;
  // Comme sur Discord : cliquer un salon vocal l'affiche et y connecte ; les salons texte restent accessibles pendant l'appel.
