  function send(e){e.preventDefault();if((!text.trim()&&!files.ids.length)||!socket.current?.connected)return;if(files.uploading)return notify('Patientez : un fichier est encore en cours d’envoi.');const typed=text,content=mention.encode(tools.prepare(text)),attachments=files.ids;setText('');tools.reset();socket.current.timeout(8000).emit('message:send',{channel:channelId,content,attachments},(err,result)=>{if(!err&&!result?.error){mention.reset();files.clear();}if(err||result?.error){setText(typed);setError(result?.error||'Le message n’a pas été envoyé. Réessayez.');}});}
