    {settingsOpen&&boot&&<AccountSettings preferences={preferences} onPreferences={setPreferences} devices={devices} onDevices={changeDevices} onVoice={voice?()=>setModal({type:'volume'}):null} user={boot.user} onBack={()=>setSettingsOpen(false)} onUserChange={user=>{setBoot(p=>({...p,user}));setDetail(p=>p?{...p,members:p.members.map(member=>member.id===user.id?{...member,username:user.username,discriminator:user.discriminator,color:user.color,avatar:user.avatar}:member)}:p);setMessages(old=>old.map(message=>message.user_id===user.id?{...message,username:user.username,color:user.color,avatar:user.avatar}:message));}} onPasswordChanged={()=>socket.current?.connect()}/>}
