      <div className="voice-stage-header"><span><Volume2 size={17}/><strong>{channel.name}</strong>{inThisCall&&<small><i className="live-dot"/> {media.isHost?'Vous hébergez cet appel':'Hébergé par un participant'}</small>}</span><IconButton icon={MessageCircle} label={voiceChat?'Masquer la discussion':'Afficher la discussion'} active={voiceChat} onClick={()=>setVoiceChat(!voiceChat)}/></div>
      {inThisCall?<div className={`voice-grid tiles-${Math.min(callTiles.length,5)}`}>{callTiles}</div>:<div className="voice-lobby"><div className="voice-lobby-icon"><Volume2 size={30}/></div><h2>{channel.name}</h2><p>{lobby?.members.length?`${lobby.members.length} personne${lobby.members.length>1?'s':''} dans ce salon`:'Personne n’est encore là. Lancez l’appel !'}</p>{!!lobby?.members.length&&<div className="voice-lobby-people">{lobby.members.map(m=><span key={m.socketId} title={m.username}><Avatar user={m} size={44}/></span>)}</div>}<button className="primary" disabled={busy||!connected||!detail?.permissions.connectVoice} onClick={()=>joinVoice(channel)}>{busy?<LoaderCircle className="spin" size={16}/>:<Headphones size={16}/>} {voice?'Changer de salon vocal':'Rejoindre le vocal'}</button>{!detail?.permissions.connectVoice&&<small>Votre rôle ne permet pas de rejoindre les salons vocaux.</small>}</div>}
