    {menu?.list&&<div className="context-menu" role="menu" style={{left:menu.x,top:menu.y}} onPointerDown={e=>e.stopPropagation()}>{detail?.permissions.manageChannels&&<><button role="menuitem" onClick={()=>{setModal({type:'channel',kind:'text'});setMenu(null);}}><Plus size={15}/> Créer un salon</button><button role="menuitem" onClick={()=>{setModal({type:'category'});setMenu(null);}}><FolderPlus size={15}/> Créer une catégorie</button></>}{detail?.permissions.inviteMembers&&<button role="menuitem" onClick={()=>{setMenu(null);invite();}}><UserPlus size={15}/> Inviter sur le serveur</button>}</div>}
