    {profileCard&&<ProfileCard key={profileCard.userId} refresh={cardVersion} voice={(room=>room&&{channelName:detail?.channels.find(c=>c.id===room.channel)?.name||'Salon vocal',members:room.members,joined:voice?.channel===room.channel})(voiceRoomOf(profileCard.userId))} onEditStatus={card=>{setProfileCard(null);setStatusEditor(card);}} onOpenVoice={()=>{const room=voiceRoomOf(profileCard.userId);setProfileCard(null);if(room){setChannelId(room.channel);setNav(false);}}} userId={profileCard.userId} anchor={profileCard.anchor} member={memberById[profileCard.userId]} server={server} roles={detail?.roles} myRank={myRank} canManageRoles={!!detail?.permissions.manageRoles&&!!memberById[profileCard.userId]&&(profileCard.userId===boot.user.id||outranks(profileCard.userId))} online={statuses[profileCard.userId]||(profileCard.userId===boot.user.id&&connected?preferences.presence:false)} onClose={()=>setProfileCard(null)} onEditProfile={tab=>{setProfileCard(null);setProfileEditor({tab});}} onMenu={ev=>memberMenu(ev,{id:profileCard.userId})} onRoles={roles=>setMemberRoles(memberById[profileCard.userId],roles)} onNotify={notify} onError={setError}/>}
