      {p.manageRoles&&(self||can)&&roles.length>0&&<><span className="context-menu-section">RÔLES</span><div className="context-menu-roles">{roles.map(r=>{const has=m.roles.includes(r.id),locked=myRank<=r.position;return <label key={r.id} className={locked?'locked':''} title={locked?'Rôle égal ou supérieur au vôtre':undefined}><input type="checkbox" checked={has} disabled={busy||locked} onChange={()=>setMemberRoles(m,has?m.roles.filter(x=>x!==r.id):[...m.roles,r.id])}/><span className="role-chip" style={{'--role-color':r.color}}><i/>{r.name}</span></label>;})}</div></>}
      {!self&&can&&(p.muteMembers||p.kickMembers||p.banMembers)&&<span className="context-menu-sep"/>}
      {!self&&can&&p.muteMembers&&<button role="menuitem" onClick={()=>{setVoiceMute(m,!m.voice_muted);setMenu(null);}}>{m.voice_muted?<Mic size={15}/>:<MicOff size={15}/>} {m.voice_muted?'Rétablir sa voix':'Rendre muet pour tous'}</button>}
      {!self&&can&&p.kickMembers&&<button role="menuitem" className="danger" onClick={()=>{setModal({type:'kick',member:m});setMenu(null);}}><LogOut size={15}/> Expulser</button>}
