      {(modal.type==='kick'||modal.type==='ban')&&<><div className="member-detail"><Avatar user={modal.member} size={56}/><p className="member-handle">{nameOf(modal.member.id,modal.member.username)} <small>({modal.member.username}#{modal.member.discriminator})</small></p></div><p className="muted">{modal.type==='ban'?'Cette personne sera retirée du serveur et ne pourra plus revenir avec une invitation, jusqu’à ce que le bannissement soit levé dans les paramètres du serveur.':'Cette personne sera retirée du serveur. Elle pourra revenir avec une nouvelle invitation.'}</p><button className="primary danger-button" disabled={busy} onClick={()=>removeMember(modal.member,modal.type)}>{modal.type==='ban'?<Ban size={16}/>:<LogOut size={16}/>} {modal.type==='ban'?'Bannir':'Expulser'}</button><button className="secondary" onClick={()=>setModal(null)}>Annuler</button></>}
      {modal.type==='category'&&<CategoryEditor key={modal.category?.id||'new'} category={modal.category} roles={detail?.roles||[]} busy={busy} onSave={body=>saveCategory(modal.category,body)} onCancel={()=>setModal(null)}/>}
      {modal.type==='delete-category'&&<><p className="muted">La catégorie <strong>{modal.category.name}</strong> sera supprimée. Ses salons ne sont pas effacés : ils remontent en haut de la liste, sans catégorie.</p><button className="primary danger-button" disabled={busy} onClick={()=>deleteCategory(modal.category)}><Trash2 size={16}/> Supprimer la catégorie</button><button className="secondary" onClick={()=>setModal(null)}>Annuler</button></>}
      {modal.type==='edit-channel'&&<ChannelEditor key={modal.channel.id} channel={modal.channel} categories={detail?.categories||[]} roles={detail?.roles||[]} busy={busy} onSave={body=>saveChannel(modal.channel,body)} onCancel={()=>setModal(null)}/>}
      {modal.type==='delete-channel'&&<><p className="muted">Le salon <strong>{modal.channel.type==='voice'?'🔊':'#'} {modal.channel.name}</strong> et tous ses messages seront supprimés définitivement pour tous les membres.{voice?.channel===modal.channel.id||rooms.some(r=>r.channel===modal.channel.id)?' L’appel en cours dans ce salon sera terminé.':''}</p><button className="primary danger-button" disabled={busy} onClick={()=>deleteChannel(modal.channel)}><Trash2 size={16}/> Supprimer le salon</button><button className="secondary" onClick={()=>setModal(null)}>Annuler</button></>}
      {modal.type==='delete-message'&&<><p className="muted">Ce message sera retiré du salon pour tous les membres.</p><blockquote>{modal.message.content}</blockquote><button className="primary" disabled={busy} onClick={()=>action(async()=>{await api(`/messages/${modal.message.id}`,{method:'DELETE'});setMessages(old=>old.filter(m=>m.id!==modal.message.id));setModal(null);})}><Trash2 size={16}/> Confirmer la suppression</button><button className="secondary" onClick={()=>setModal(null)}>Annuler</button></>}
